      "example": "2026-10-24 09:00:00"
    },
    "scopes": {
      "type": "array",
      "items": {
        "type": "string",
        "maxLength": 30
      },
      "description": "Permisiuni cerute. Rolul și apartenența curente limitează suplimentar fiecare cerere."
    },
    "secret_available": {
      "type": "boolean",
      "description": "true numai la prima livrare a cheii. La reluare este false și token lipsește."
    },
    "previous_revoked": {
      "type": "boolean",
      "description": "true numai la prima livrare a cheii. La reluare este false și token lipsește."
    },
