    }
  },
  "required": [
    "id",
    "expires_at",
    "scopes",
    "secret_available"
  ],
  "additionalProperties": false,
  "description": "Structura KeyIssuance. Exemplele sunt sintetice; permisiunile și stările reale se verifică la cerere."
}
```

